# -*- coding: utf-8 -*-
# Diapositivas del pack «Tertuliano, trinitario». Latín tomado de los JSON de los investigadores (T1-T11); traducción al español mía.
import re
from lib import ALL

def clean(t):
    t = t.replace('oi0konomi/an', 'oikonomían').replace('probolh_n', 'probolḗn').replace('probolh_', 'probolḗ').replace('�', '')
    return re.sub(r'\s+', ' ', t).strip()

def Q(pid, es, a=None, b=None, ref=None, src=None, tag=None, en=None):
    p = ALL[pid]
    lat = clean(en) if en else clean(p['latin'])
    if a:
        i = lat.index(a); lat = lat[i:]
    if b:
        j = lat.index(b) + len(b); lat = lat[:j]
    return dict(id=pid, lat=lat, es=es, ref=ref or p['ref'].split('(')[0].strip(), work=p['work'].split('(')[0].strip(), src=src or '', tag=tag or '', page=str(p.get('page', '')), status=p.get('status', ''), lang=('en' if en else 'la'))

S = []

# ---------------------------------------------------------------- 1 vocabulario
S.append(dict(id='TQ01', title='El vocabulario de Tertuliano: una sustancia, tres «personas»',
 sub='Adversus Praxean 2, 9 y 12: de dónde viene «trinitas» y qué quiere decir cada término',
 quotes=[
  Q('T1-04', 'como si no fuera todo de uno solo, al ser todo desde uno, por la unidad de la sustancia, y sin embargo se guardase el misterio de la economía, que dispone la unidad en trinidad, ordenando a tres: Padre, Hijo y Espíritu', a='quasi non sic quoque unus sit omnia', ref='Adv. Prax. 2.4', src='Kroymann, CSEL 47, p. 229 (primer uso de «trinitas»)'),
  Q('T1-05', 'tres, sin embargo, no en condición sino en grado; no en sustancia sino en forma; no en poder sino en aspecto; pero de una sola sustancia, una sola condición y un solo poder, porque es un solo Dios, del cual se cuentan esos grados, formas y aspectos bajo el nombre del Padre, del Hijo y del Espíritu Santo', a='tres autem non statu', ref='Adv. Prax. 2.4', src='Kroymann, p. 230'),
  Q('T3-14', 'Cómo debes entender «otro», ya lo he declarado: por el nombre de persona, no de sustancia; para distinguir, no para dividir. Por lo demás, aunque mantengo en todas partes una sola sustancia en tres que están unidos, hay que decir «otro» por necesidad del sentido: el que manda y el que ejecuta', a='alium autem quomodo accipere debeas', ref='Adv. Prax. 12.3', src='Kroymann; ANF: «on the ground of Personality, not of Substance»'),
 ],
 res='<b>Lectura.</b> Tertuliano no usa «persona» como máscara ni «sustancia» como materia: dice que Padre, Hijo y Espíritu son <i>tres</i> («tres… non statu sed gradu») <i>de una sola sustancia</i> («unius substantiae»), y que «otro» (<i>alius</i>) se dice «de persona, no de sustancia; para distinguir, no para dividir». Es el núcleo de la fórmula que la tradición posterior fijó (una <i>ousía</i>/sustancia, tres <i>hipóstasis</i>/personas). <b>Límite:</b> sus términos no son todavía los de Nicea (usa <i>status</i>, <i>gradus</i>, <i>forma</i>, <i>species</i>, y piensa «sustancia» con rasgos estoicos).'))

S.append(dict(id='TQ02', title='Una sola sustancia: no dividida ni separada',
 sub='Adversus Praxean 8, 13 y 25 · Apologeticum 21',
 quotes=[
  Q('T6-03', 'el Espíritu es tercero a partir de Dios y del Hijo, como el fruto es tercero a partir de la raíz, por el arbusto; y el arroyo, tercero a partir de la fuente, por el río; y el vértice del rayo, tercero a partir del sol. Nada, sin embargo, se aparta de la matriz de la que toma sus propiedades. Así la trinidad, descendiendo del Padre por grados unidos y trabados, no estorba en nada a la monarquía y protege el orden de la economía', a='secundus autem ubi est', ref='Adv. Prax. 8.7', src='Kroymann, CSEL 47, p. 239'),
  Q('T4-08', 'Pues también al rayo del sol, tomado aparte, lo llamaré sol; pero al nombrar el sol de quien es el rayo, no llamaré enseguida sol al rayo. Y aunque haga dos soles, contaré al sol y a su rayo como dos cosas y dos aspectos de una sola e indivisa sustancia, como a Dios y a su Verbo, como al Padre y al Hijo', a='nam et radium solis seorsum solem vocabo', ref='Adv. Prax. 13.10', src='Latin Library; ANF cap. 13'),
  Q('T4-24', 'Así la conexión del Padre en el Hijo y del Hijo en el Paráclito produce tres unidos, uno desde el otro. Estos tres son uno, no «uno solo», como se dijo: «Yo y el Padre somos uno», en cuanto a la unidad de sustancia, no a la singularidad de número', a='ita connexus patris in filio', ref='Adv. Prax. 25.1', src='Latin Library; ANF cap. 25'),
  Q('T8-03', 'Así también lo que ha salido de Dios es Dios e Hijo de Dios, y los dos son uno; así también de espíritu, espíritu, y de Dios, Dios: por la medida hizo otro, por el grado hizo número, no por el estado; y no se alejó de la matriz, sino que salió de ella', a='Ita et quod de deo profectum est', ref='Apol. 21.13', src='Latin Library; Oehler p. 94'),
 ],
 res='<b>Lectura.</b> La imagen que usa Tertuliano (raíz–arbusto, fuente–río, sol–rayo) está hecha para <i>excluir la separación</i>: «nihil a matrice alienatur», «no se separa la sustancia sino que se extiende» (Apol. 21.12). Eso es exactamente lo que dirá Nicea con «Dios de Dios, luz de luz». Y «uno, no uno solo» (<i>unum, non unus</i>) es la distinción entre unidad de sustancia y singularidad de persona, que niega el modalismo de Praxeas.'))

S.append(dict(id='TQ03', title='Tres distintos: el Hijo y el Espíritu no son «modos» del Padre',
 sub='Adversus Praxean 9, 10 y 12 · contra Praxeas («el Padre sufrió»)',
 quotes=[
  Q('T3-02', 'Mira, digo que el Padre es uno, otro el Hijo y otro el Espíritu: cualquier ignorante o perverso toma mal este dicho, como si sonara a diversidad y de la diversidad se siguiera la separación del Padre, del Hijo y del Espíritu Santo', a='ecce enim dico alium esse patrem', ref='Adv. Prax. 9.1', src='Kroymann; ANF cap. 9'),
  Q('T3-03', 'no por diversidad es otro el Hijo respecto del Padre, sino por distribución; no es otro por división, sino por distinción, porque Padre e Hijo no son lo mismo, y difieren por su modo de ser', a='non tamen diuersitate alium filium a patre', ref='Adv. Prax. 9.2', src='Kroymann; ANF cap. 9'),
  Q('T3-09', 'Es necesario que el Padre tenga Hijo para ser Padre, y el Hijo Padre para ser Hijo. Pero una cosa es tener, otra ser: por ejemplo, para ser marido debo tener esposa; yo no seré esposa de mí mismo', a='habeat necesse est pater filium', ref='Adv. Prax. 10.2', src='Kroymann; ANF cap. 10'),
  Q('T6-05', 'más bien, porque ya estaba junto a él el Hijo, segunda persona, su Verbo, y la tercera, el Espíritu en el Verbo, habló en plural: «hagamos», «nuestra», «a nosotros»', a='immo, quia iam adhaerebat illi', ref='Adv. Prax. 12.3', src='Kroymann; ANF cap. 12'),
 ],
 res='<b>Lectura.</b> Tertuliano defiende dos tesis a la vez, como Nicea: (1) <i>tres</i> que se distinguen realmente («alius… alius… alius»); (2) <i>no</i> tres dioses ni tres sustancias. Su argumento relacional («para ser padre hay que tener hijo») es el mismo que usará la tradición para fundar que Padre e Hijo son relaciones distintas dentro de una misma esencia.'))

S.append(dict(id='TQ04', title='El Hijo y el Espíritu son Dios',
 sub='Adversus Praxean 13 · Adversus Hermogenem 18 y 20',
 quotes=[
  Q('T4-01', 'Sin embargo, nunca sale de nuestra boca «dos dioses» o «dos señores»: no como si el Padre no fuera Dios, y el Hijo Dios, y el Espíritu Santo Dios, y cada uno Dios; sino porque antes se predicaban dos dioses y dos señores, para que, cuando viniera Cristo, fuera reconocido como Dios y llamado Señor por ser Hijo de Dios y del Señor', a='duos tamen deos et duos dominos', ref='Adv. Prax. 13.6', src='Latin Library; ANF cap. 13'),
  Q('T4-06', 'Por lo demás, si por la conciencia con que sabemos que el nombre de Dios y de Señor conviene al Padre, al Hijo y al Espíritu, nombráramos dioses y señores, habríamos apagado nuestras antorchas', a='ceterum si ex conscientia', ref='Adv. Prax. 13.8', src='Latin Library; ANF cap. 13'),
  Q('T7-10', 'Usaré el Evangelio como complemento del Antiguo Testamento: «En el principio era el Verbo» —en el principio en el que Dios hizo el cielo y la tierra— «y el Verbo estaba junto a Dios y el Verbo era Dios. Todo fue hecho por él y sin él nada fue hecho»', a='In principio erat sermo', ref='Adv. Herm. 20.4', src='Kroymann; ANF cap. 20'),
  Q('T7-08', 'Si la sabiduría es el mismo Verbo de Dios, sin el cual nada fue hecho, ¿cómo va a existir algo más antiguo que el Padre para el Hijo de Dios, Verbo unigénito y primogénito?', a='Si uero sophia eadem dei sermo est', b='primogenito', ref='Adv. Herm. 18.3', src='Kroymann; ANF cap. 18 (cita recortada)'),
 ],
 res='<b>Lectura.</b> «Pater deus et filius deus et spiritus sanctus deus, et deus unusquisque» (Prax. 13.6): la divinidad de las tres personas está dicha sin ambages. Lo que Tertuliano evita es llamarlos «dioses» en plural, para no incurrir en el politeísmo. Nada en ello es arriano.'))

S.append(dict(id='TQ05', title='El Espíritu Santo: «tercer nombre de la divinidad»',
 sub='Adversus Praxean 8, 12, 30 y 31 · De Pudicitia 21 · De Baptismo 13',
 quotes=[
  Q('T6-11', 'derramó el don recibido del Padre, el Espíritu Santo, tercer nombre de la divinidad y tercer grado de la majestad, pregonero de la única monarquía y también intérprete de la economía, y guía hacia toda la verdad, que está en el Padre, en el Hijo y en el Espíritu Santo según el sacramento cristiano', a='interim acceptum a patre munus effudit', ref='Adv. Prax. 30', src='Kroymann, CSEL 47'),
  Q('T6-13', 'Pues la Iglesia misma, propia y principalmente, es el Espíritu, en el cual está la trinidad de una sola divinidad: Padre, Hijo y Espíritu Santo', a='Nam et ipsa ecclesia', ref='De Pudicitia 21.16', src='Latin Library; ANF vol. 4, p. 224'),
  Q('T6-15', '«Id», dijo, «enseñad a las naciones, bautizándolas en el nombre del Padre, del Hijo y del Espíritu Santo»', a='Ite, inquit, docete nationes', b='spiritus sancti', ref='De Baptismo 13.3', src='Latin Library; ANF vol. 3'),
 ],
 res='<b>Lectura.</b> «Tertium nomen divinitatis» (Prax. 30) y «trinitas unius divinitatis» (Pud. 21): Tertuliano dice «divinidad» —no «criatura»— del Espíritu, y lo coloca en la misma fórmula bautismal. <b>Ojo:</b> el encargo suponía que el bautismo trino estaba en <i>De Baptismo</i> 6 y 8; el investigador comprobó que está en 13.3 (y la triple inmersión en <i>De Corona</i> 3.3). Aquí se cita el pasaje real.'))

S.append(dict(id='TQ06', title='Las reglas de fe de Tertuliano',
 sub='De Praescriptione 13 · Adversus Praxean 2 · De Virginibus Velandis 1',
 quotes=[
  Q('T8-05', 'Creemos en un solo Dios, pero bajo esta dispensación, que llamamos economía, de modo que del Dios único sea también el Hijo, su Verbo, que procedió de él, por quien todo fue hecho y sin quien nada fue hecho; a este lo envió el Padre a la Virgen, y nació de ella hombre y Dios, Hijo del hombre e Hijo de Dios […] y envió después, según su promesa, del Padre, al Espíritu Santo Paráclito, santificador de la fe de los que creen en el Padre, en el Hijo y en el Espíritu Santo', a='unicum quidem deum credimus', ref='Adv. Prax. 2.1', src='Kroymann; ANF cap. 2 (texto recortado)'),
  Q('T8-04', 'Que hay un solo Dios y ningún otro fuera del creador del mundo, que lo produjo todo de la nada por su Verbo, emitido el primero de todo. Este Verbo, llamado su Hijo, en nombre de Dios fue visto de diversos modos por los patriarcas, oído siempre en los profetas y por último llevado, por el Espíritu y poder de Dios Padre, a la Virgen María, hecho carne en su seno y nacido de ella como Jesucristo', a='Vnum omnino Deum esse', ref='De Praescr. 13.2-3', src='Latin Library; ANF vol. 3, p. 249'),
 ],
 res='<b>Lectura.</b> Las dos reglas nombran a Padre, Hijo y Espíritu; la de <i>Adv. Prax.</i> 2 es la más completa. <b>Ojo (resultado negativo):</b> en <i>De Virginibus Velandis</i> 1.4 la regla de fe solo menciona a Dios y a su Hijo, sin Espíritu (el «(as of the spirit)» de la ANF es añadido del traductor), y no hay allí fórmula trinitaria; no se usa. Y en <i>De Praescr.</i> 13 el Espíritu aparece como «espíritu y poder de Dios Padre», más cercano a una fórmula cristológica que a una plenamente trinitaria; por eso <i>Adv. Prax.</i> 2 es el texto que cuenta.'))

# ---------------------------------------------------------------- pasajes duros
S.append(dict(id='TQ07', title='Pasaje duro 1: «hubo un tiempo en que no existían el pecado ni el Hijo»',
 sub='Adversus Hermogenem 3: lo que dice, en su contexto',
 quotes=[
  Q('T7-02', 'Decimos que el nombre de Dios existió siempre junto a sí mismo y en sí mismo, pero no siempre el de Señor. Pues la condición de ambos es diversa: «Dios» es el nombre de la sustancia misma, es decir, de la divinidad; «Señor», en cambio, no lo es de sustancia sino de poder', a='Dei nomen dicimus semper fuisse', b='non substantiae sed potestatis', ref='Adv. Herm. 3.3', src='Kroymann; ANF cap. 3'),
  Q('T7-03', 'Pues ni pudo ser Padre antes del Hijo ni juez antes del delito. Hubo, sin embargo, un tiempo en que no existían para él ni el delito ni el Hijo: el primero, que lo haría juez; el segundo, que lo haría Padre', a='nam nec pater potuit esse ante filium', b='et filius non fuit', ref='Adv. Herm. 3.4', src='texto de la Latin Library («cum ei delictum»); Kroymann (CSEL 47, p. 129, ver TQ15) lee «cum et delictum»; ANF cap. 3'),
  Q('T7-04', '¿Parezco argumentarte, Hermógenes? La Escritura nos defiende con empeño, pues distinguió ambos nombres y los muestra a su tiempo. Porque «Dios» lo nombra de inmediato, pues lo era siempre: «En el principio hizo Dios el cielo y la tierra»; pero mientras hacía aquello de lo que sería Señor, solo pone «Dios». […] Cuando lo hubo terminado todo, entonces añadió también el nombre de «Señor»', a='Argumentari tibi uideor, Hermogenes?', ref='Adv. Herm. 3.5', src='Kroymann; ANF cap. 3 (texto recortado)'),
 ],
 res='<b>Qué dice.</b> En todo el capítulo Tertuliano combate a Hermógenes, que quería probar que la materia fue eterna porque Dios fue siempre «Señor». Responde que <i>Dios</i> (nombre de la sustancia) es eterno, pero <i>Señor, Padre, Juez</i> son nombres <i>relativos</i> que Dios «adquiere» en el tiempo («accedentis rei mentio»). Para «Padre» e «Hijo» aplica lo mismo: «ni pudo ser Padre antes del Hijo». <b>Honestidad:</b> tomado a la letra, «fuit tempus cum… filius non fuit» es lo que Arrio dirá y Nicea condenará. No se puede «explicar» esa frase sin más: hay que reconocer que Tertuliano, aquí, habla con lenguaje preniceno que Nicea corregirá. La respuesta está en la diapositiva siguiente.'))

S.append(dict(id='TQ08', title='Resolución del pasaje 1: qué sostiene Tertuliano y qué corrige Nicea',
 sub='Su propia distinción entre Razón eterna y «nacimiento perfecto» del Verbo, y la metafísica que lo resuelve después',
 quotes=[
  Q('T2-02', 'Antes de todo, Dios estaba solo, para sí mundo y lugar y todo. Solo, porque nada había fuera de él. Pero ni siquiera entonces estaba solo: tenía consigo la razón que tenía en sí mismo, la suya. Pues Dios es racional, y la razón está primero en él, y así todo viene de él: esa razón es su pensamiento', a='ante omnia enim deus erat solus', b='quae ratio sensus ipsius est', ref='Adv. Prax. 5.2', src='Latin Library; ANF cap. 5'),
  Q('T7-07', 'Reconozca, pues, Hermógenes que se predica a la sabiduría de Dios «nacida» y «creada» para que no creyéramos que hay algo ingénito e increado fuera del solo Dios […]', a='Agnoscat ergo Hermogenes', b='praeter solum deum crederemus', ref='Adv. Herm. 18.2', src='Kroymann; ANF cap. 18 (recortado)'),
  Q('T10-14', 'Nunca el Verbo no existió, sino que existió siempre, coexistiendo eternamente con el Padre, como el resplandor de la luz', ref='Atanasio, De Decretis 20', src='NPNF (newadvent.org/fathers/2809.htm); original griego no consultado; traducción mía del inglés', en='for never was the Word not, but He was always, existing everlastingly with the Father, as the radiance of light'),
  Q('T10-26', 'En Dios la relación no es un todo universal […]: todas las relaciones juntas no son más que una sola, ni todas las personas son algo mayor que una sola, porque toda la perfección de la naturaleza divina está en cada persona', ref='Tomás de Aquino, ST I, q.42 a.4 ad 3', src='newadvent.org/summa/1042.htm (traducción inglesa); latín no consultado; traducción mía', en='all the relations together are not greater than only one; nor are all the persons something greater than only one; because the whole perfection of the divine nature exists in each person.'),
 ],
 res='<b>1. Lo que dice Tertuliano.</b> Distingue (a) la <i>Razón</i> divina, que está en Dios «antes de todo» (Prax. 5.2), y (b) el <i>Verbo/Hijo</i> como persona proferida para crear («natividad perfecta», Prax. 7.1). En Herm. 18.2 llama a la Sabiduría «nacida y creada» y en Herm. 3.4 dice que no hubo Hijo ni delito «antes». Kaye (ANF) lo resume: «asigna a ambos [Sabiduría e Hijo] un comienzo de existencia» (TQ13). <b>Esto no es la generación eterna de Nicea y no se puede fingir que lo sea.</b><br><b>2. Lo que sí queda a salvo.</b> Aun en estos pasajes (a) el Hijo no es criatura: es «unigénito y primogénito», «sin él nada fue hecho» y «unius substantiae»; (b) Tertuliano distingue lo que Dios es (sustancia, nombre «Dios») de lo que Dios es respecto de otro (Señor, Juez, Padre); (c) la analogía «Padre/Juez» cojea: «juez» supone un delito contingente; «Padre» supone un Hijo que, para Tertuliano, es de la misma sustancia.<br><b>3. Metafísica posterior.</b> Atanasio: «nunca el Verbo no existió» (De Decr. 20); la generación es de la esencia, no un acto de voluntad ni una obra externa (De Decr. 23: «propia e indivisible»). Aquino: generar pertenece a la naturaleza divina, no a la voluntad, y las relaciones son reales y eternas (ST I, q.27; q.42 a.4 ad 3). Con ello la frase «hubo un tiempo en que no era» queda excluida; Tertuliano no la había excluido todavía.<br><b>Veredicto.</b> Tertuliano es trinitario en sustancia (una sustancia, tres personas, Hijo y Espíritu divinos) pero su lenguaje sobre la <i>generación</i> es pre-niceno; defenderlo no exige negarlo.'))

S.append(dict(id='TQ09', title='Pasaje duro 2: «el Hijo, derivación y porción del todo»',
 sub='Adversus Praxean 9 y 26 · Apologeticum 21',
 quotes=[
  Q('T3-04', 'Pues el Padre es toda la sustancia, y el Hijo, derivación y porción del todo, como él mismo declara: «El Padre es mayor que yo»', a='pater enim tota substantia est', ref='Adv. Prax. 9.2', src='Kroymann; Souter p. 46 (inferida)'),
  Q('T3-06', 'Bien: el Señor, al usar este término a propósito del Paráclito, no significó división sino disposición: «Rogaré al Padre y os enviará otro abogado, el Espíritu de la verdad», así «otro» respecto de sí, como nosotros decimos «otro» el Hijo respecto del Padre, para mostrar un tercer grado en el Paráclito, como un segundo en el Hijo, por la observancia de la economía', a='bene, quod et dominus usus hoc uerbo', ref='Adv. Prax. 9.3', src='Kroymann; ANF cap. 9'),
  Q('T5-09', 'Al decir «Espíritu de Dios» —aunque el Espíritu de Dios es Dios—, sin nombrar directamente a Dios, quiso que se entendiera «porción del todo», que habría de ceder en el nombre del Hijo', a='Dicens autem Spiritus Dei', ref='Adv. Prax. 26.3', src='Migne PL 2, vía Wikisource; Kroymann trae «**» en esta línea'),
  Q('T8-02', 'Y cuando el rayo se extiende desde el sol, es porción del conjunto; pero el sol estará en el rayo, porque el rayo es del sol, y no se separa la sustancia, sino que se extiende […] como luz de luz encendida. La matriz permanece íntegra y sin menoscabo, aunque tomes de ella muchos conductos de cualidad', a='Et cum radius ex sole porrigitur', ref='Apol. 21.12', src='Latin Library (texto con corchetes del editor); Oehler p. 94'),
 ],
 res='<b>Qué dice.</b> Tertuliano usa «portio» y «derivatio» para decir que el Hijo <i>procede</i> del Padre y no es el Padre; pero el contexto inmediato dice «no por división sino por distinción» (9.2). En 26.3 usa «portio totius» <i>del Espíritu</i>, a quien acaba de llamar «Dios». <b>Honestidad:</b> «portio» es la palabra más desafortunada de Tertuliano: a la letra sugiere parte y por tanto menos. Nicea la corregirá: «de la sustancia del Padre», «consustancial», sin partes. La defensa de que él no la entiende como parte está en la diapositiva siguiente.'))

S.append(dict(id='TQ10', title='Resolución del pasaje 2: «porción» sin partes',
 sub='Bull, Hilario, Atanasio y Tomás de Aquino sobre «parte» y «todo» en Dios',
 quotes=[
  Q('T9-11', 'Una parte es menor que el todo del que se toma; el Hijo, en cambio, es en todo (salvo el ser Hijo) semejante e igual al Padre, y tiene y posee todo lo que tiene el Padre', ref='G. Bull, Defensio Fidei Nicaenae, cap. VII, p. 200', src='PDF abierto (archive.org), versión inglesa de la ed. Parker 1851; traducción mía', en='A part is less than the whole from which it is taken; the Son, however, is in all respects, (excepting that He is the Son,) like, and equal to the Father, and has and possesses all that the Father has.'),
  Q('T10-29', 'Ni hay una porción del Padre residente en el Hijo: el Hijo mismo da testimonio de que todo lo que tiene el Padre es suyo; y por la naturaleza de las cosas una porción no puede poseer el todo', ref='Hilario de Poitiers, De Trinitate 2.8', src='NPNF (newadvent.org); latín no consultado; traducción mía', en='Nor is there a portion of the Father resident in the Son ... and by the nature of things a portion cannot possess the whole.'),
  Q('T10-15', 'Los santos no dijeron que el Verbo se relacione con Dios como el fuego encendido del calor del sol, que suele apagarse de nuevo —pues eso es obra externa y criatura de su autor—, sino que lo predican como Resplandor, para significar que es de la esencia, propio e indivisible, y uno con el Padre', ref='Atanasio, De Decretis 23', src='NPNF (newadvent.org/fathers/2809.htm); griego no consultado; traducción mía del inglés', en='For the Saints have not said that the Word was related to God as fire kindled from the heat of the sun, which is commonly put out again, for this is an external work and a creature of its author, but they all preach of Him as Radiance, thereby to signify His being from the essence, proper and indivisible, and His oneness with the Father.'),
  Q('T10-27', 'El Hijo es necesariamente igual al Padre en grandeza, pues la grandeza de Dios no es sino la perfección de su naturaleza', ref='Tomás de Aquino, ST I, q.42 a.4', src='newadvent.org/summa/1042.htm (traducción inglesa); latín no consultado; traducción mía', en='The Son is necessarily equal to the Father in greatness. For the greatness of God is nothing but the perfection of His nature.'),
 ],
 res='<b>1. El texto mismo.</b> Tertuliano niega que la «derivación» sea separación: «no se separa la sustancia sino que se extiende» (Apol. 21.12), «nada se aparta de la matriz» (Prax. 8.7), «una e indivisa sustancia» (Prax. 13.10), «ad substantiae unitatem» (25.1). «Portio» se predica del Espíritu en la misma frase en que dice que es Dios (26.3).<br><b>2. Bull (Defensio, 1685).</b> Entiende «portio» como «derivación sin merma»: «una parte es menor que el todo; el Hijo es igual al Padre» (p. 200). Su respuesta es una afirmación, no una prueba: no discute Jn 14:28 en esa frase.<br><b>3. Metafísica.</b> Una «parte» supone composición y menor perfección; Dios es simple e infinito y no tiene partes. Hilario: «una porción no puede poseer el todo»; Atanasio: la generación es «de la esencia, propia e indivisible», no una obra externa; Aquino: la grandeza de Dios es la perfección de su naturaleza, que está entera en cada persona, y el Hijo es por tanto igual al Padre.<br><b>4. Lectura de Tertuliano.</b> Con «Pater tota substantia» quiere decir que el Padre es el origen que posee la naturaleza entera, y con «portio» que el Hijo la recibe de él. Es una expresión imprecisa para «derivación» —que Hilario y Atanasio corrigieron—, no una doctrina de partes.'))

S.append(dict(id='TQ11', title='«El Padre es mayor», «segundo», «vicario»: subordinación de orden, no de naturaleza',
 sub='Adversus Praxean 9, 19, 24 y 25',
 quotes=[
  Q('T3-05', 'por eso en el salmo se canta que fue hecho «un poco menor que los ángeles». Así el Padre es otro que el Hijo, al ser mayor que el Hijo, al ser otro el que engendra y otro el que es engendrado, otro el que envía y otro el que es enviado, otro el que hace y otro por quien se hace', a='a quo et minoratus canitur in psalmo', ref='Adv. Prax. 9.2', src='Kroymann; ANF cap. 9'),
  Q('T5-07', 'Si no quieren que se tenga al Hijo por segundo respecto del Padre, para que el segundo no haga decir dos dioses, hemos mostrado que en la Escritura se mencionan también dos dioses y dos señores; […] y esto no por separación de sustancia, sino por disposición, cuando proclamamos al Hijo individuo e inseparado del Padre; otro no por estado, sino por grado', a='Si Filium nolunt secundum a Patre reputari', b='nec statu, sed gradu alium', ref='Adv. Prax. 19.7', src='Migne PL 2 (Wikisource); ANF cap. 19 (recortado)'),
  Q('T4-23', 'según esto se había mostrado como «vicario» del Padre, por quien el Padre fuera visto en las obras y oído en las palabras y conocido en el Hijo, administrando los hechos y las palabras del Padre', a='secundum haec enim vicarium se patris ostenderat', b='administrante', ref='Adv. Prax. 24', src='Latin Library; ANF cap. 24 (recortado)'),
 ],
 res='<b>Qué dice.</b> «Mayor», «segundo» y «vicario» aparecen en frases donde Tertuliano añade «no por separación de sustancia sino por disposición», «no por estado sino por grado» (19.7). Y el «otro» del Paráclito lo explica por «la observancia de la economía» (9.3).<br><b>Metafísica.</b> Se distingue <i>naturaleza</i> (la misma) y <i>origen/orden</i> (el Hijo viene del Padre). Nicea dirá: igual en divinidad, «de» el Padre en origen. Aquino lo formula así: la grandeza de Dios es la perfección de su naturaleza y está entera en cada persona (ST I, q.42 a.4); no hay mayor ni menor en la naturaleza.<br><b>Honestidad:</b> Tertuliano no tiene todavía esa distinción de modo explícito, y «minoratus» y «vicarium» sonarán subordinacionistas a oídos postnicenos (los investigadores T4 y T5 lo marcaron como no resoluble solo con el texto). Es una subordinación <i>económica y de origen</i>, no de naturaleza, y eso es lo que Nicea precisó con «consustancial».'))

S.append(dict(id='TQ12', title='Pasaje duro 3: «natividad perfecta» del Verbo en la creación',
 sub='Adversus Praxean 6 y 7',
 quotes=[
  Q('T2-08', 'Pues apenas Dios quiso sacar a la luz, en sus sustancias y especies, lo que había dispuesto dentro de sí con la sabiduría, la razón y el Verbo, produjo primero al Verbo mismo, que tiene en sí su razón y su sabiduría, para que por él se hicieran todas las cosas, por quien habían sido pensadas y dispuestas, y más aún, ya hechas en cuanto a la mente de Dios', a='nam ut primum deus voluit ea quae', ref='Adv. Prax. 6.3', src='Latin Library; ANF cap. 6'),
  Q('T2-09', 'Entonces, pues, el Verbo mismo toma su forma y su ornato, sonido y voz, cuando dice Dios: «Hágase la luz». Esta es la natividad perfecta del Verbo, cuando procede de Dios', a='Tunc igitur etiam ipse sermo', ref='Adv. Prax. 7.1', src='Latin Library; ANF cap. 7'),
  Q('T2-16', 'Esta será la prolación de la verdad, custodia de la unidad, por la que decimos que el Hijo es proferido por el Padre, pero no separado. Pues Dios profirió el Verbo, como también enseña el Paráclito, como la raíz el arbusto, la fuente el río y el sol el rayo', a='haec erit probolḗ veritatis', ref='Adv. Prax. 8.5', src='Latin Library; ANF cap. 8'),
 ],
 res='<b>Qué dice.</b> El Verbo ya existe en Dios (Prax. 5); lo que tiene lugar «cuando Dios dice: Hágase la luz» es la «natividad perfecta» —su salida visible, voz y forma— y es la segunda etapa de lo que Tertuliano llama «prolación». Es la parte más cuestionada por los intérpretes: Bull la defiende como «generación» en sentido amplio, Newman reconoce que Tertuliano fecha el nacimiento perfecto del Hijo en la creación (T9-05, T9-06).<br><b>Resolución.</b> Nicea distingue la <i>generación eterna</i> (el Hijo recibe del Padre todo el ser, sin tiempo) de la <i>misión</i> y <i>manifestación</i> (el Verbo sale «ad extra» para crear y revelar). Tertuliano mezcla ambas en la palabra «prolación»; su insistencia en que lo proferido «no es separado» (8.5) es el eje común.'))

S.append(dict(id='TQ13', title='Qué dicen los estudiosos: defensa y concesión',
 sub='Bull y Kaye, citados con lo que se pudo ver; lo que no está abierto no se cita',
 quotes=[
  Q('T9-08', 'Lee solo su único tratado contra Praxeas, en el que trata plena y expresamente de la santísima Trinidad: allí afirma la consustancialidad del Hijo con tanta frecuencia y claridad que creerías que el autor escribió después del concilio de Nicea', ref='G. Bull, Defensio Fidei Nicaenae, cap. VII, p. 193', src='PDF abierto (archive.org); traducción mía del inglés', en='Read only his single work against Praxeas, in which he treats fully and professedly of the most holy Trinity; he there asserts the consubstantiality of the Son so frequently and so plainly, that you would suppose the author had written after the time of the Nicene council.'),
  Q('T9-16', 'El obispo Bull, que considera explícito y correcto el lenguaje de Tertuliano sobre la preexistencia y la consustancialidad, admite que a veces usa expresiones en desacuerdo con la coeternidad de Cristo: por ejemplo, en el tratado contra Hermógenes se afirma expresamente que hubo un tiempo en que el Hijo no existía', ref='J. Kaye, nota en ANF vol. 3', src='ANF vol. 3 (nota de Kaye; páginas 504-596 según la ANF, página exacta no vista); traducción mía', en='Bp. Bull also ... admits that he occasionally uses expressions at variance with the co-eternity of Christ ... in the Tract against Hermogenes ... we find a passage in which it is expressly asserted that there was a time when the Son was not.'),
  Q('T9-17', 'Respecto de la Sabiduría y del Hijo el caso es distinto. Tertuliano asigna a ambos un comienzo de existencia: la Sabiduría fue creada o formada para idear el plan del universo, y el Hijo fue engendrado para llevarlo a efecto', ref='J. Kaye, nota en ANF vol. 3', src='ANF vol. 3 (nota de Kaye); traducción mía', en='But with respect to Wisdom and the Son (Sophia and Filius) the case is different. Tertullian assigns to both a beginning of existence: Sophia was created or formed in order to devise the plan of the universe; and the Son was begotten in order to carry that plan into effect.'),
  Q('T9-18', 'No pretendemos afirmar que no puedan encontrarse a veces expresiones capaces de otra interpretación, y que los escritores ortodoxos de épocas posteriores evitaron con cuidado, cuando las controversias sobre la Trinidad habían introducido mayor precisión de lenguaje', ref='J. Kaye, nota en ANF vol. 3', src='ANF vol. 3 (nota de Kaye); traducción mía', en='We are far from meaning to assert that expressions may not occasionally be found which are capable of a different interpretation, and which were carefully avoided by the orthodox writers of later times, when the controversies respecting the Trinity had introduced greater precision of language.'),
 ],
 res='<b>Lo verificado.</b> Un defensor (Bull, 1685) dice que <i>Adv. Prax.</i> afirma la consustancialidad con tanta claridad como si fuera posterior a Nicea; y los dos que explican <i>Adv. Herm.</i> 3 (Bull según Kaye, y Kaye) admiten que hay expresiones «en desacuerdo con la coeternidad» y que Tertuliano da «un comienzo de existencia» a la Sabiduría y al Hijo. Newman cita <i>Adv. Herm.</i> 3 como «hubo un tiempo en que el Hijo no era» (<i>Arians</i>, p. 417; su frase no es literal de Tertuliano).<br><b>Lo que no pude leer:</b> Kelly, Evans, Osborn, Barnes, Daniélou, Moingt y Hanson (sin texto abierto); no los cito. <b>Veredicto del pack:</b> Tertuliano es trinitario en sustancia —una sustancia, tres personas, Hijo y Espíritu divinos, y por eso Bull lo defiende— pero usa lenguaje pre-niceno sobre la generación del Hijo, que Nicea corrigió. No es arriano: no hace del Hijo una criatura.'))
